import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

public class ResilientService {

    public String fetchUserData(String userId) {
        return CompletableFuture.supplyAsync(() -> callExternalService(userId))
                .orTimeout(800, TimeUnit.MILLISECONDS)
                .exceptionally(ex -> fallbackUserData(userId, ex));
    }

    private String callExternalService(String userId) {
        // Simulate network latency or failure
        return "Remote Data for " + userId;
    }

    private String fallbackUserData(String userId, Throwable ex) {
        // Log the exception (timeout or service down)
        System.err.println("Fallback triggered due to: " + ex.getMessage());
        return "Cached/Default Data for " + userId;
    }
}
